import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register, RenderInput } from 'claude-code'

import type { Board, Limit, LookItem, LookQueue, SpriteSet, View } from '../types'
import { prepareAsk } from './ask'
import { bandView } from './band'
import { parseBoard } from './board'
import { messages, type Lang } from './i18n'
import { addItem, markOpened, parseQueue, removeItem } from './look'
import { moodFromReply, moodOf } from './mood'
import { ACTIVE_CONTENT_EXTENSIONS, COMMAND_TIMEOUT_MS, detectPlatform, extensionOf, planOpen, type OpenDecision, type OpenPlan } from './open'
import { isInside } from './paths'
import { paneView } from './pane'
import { scopeOf, type Scoped } from './scope'
import { buildRuntime, readSettings, type Runtime } from './settings'
import { isSleepCommand, isSleepSkill } from './sleep'
import { MAX_SPRITE_FILE_BYTES, parseSprites } from './sprites'
import { LOOK_TOOL, PANE } from './constants'
import { utcOffsetMinutes } from './time'
import { usageRows } from './usage'

// The engine follows `$` and the state atoms only within this file, so the atoms below and everything that
// touches the machine (files, commands, the pane) live here; the pure parts are in the neighbouring modules.
//
// Reactive state, shared by the pane and the band (the types are declared in types/index.d.ts).
const board = atom({ plugin: 'companion', key: 'board' } as const, null)
const last = atom({ plugin: 'companion', key: 'last' } as const, null)
const isBandHidden = atom({ plugin: 'companion', key: 'isBandHidden' } as const, false)
const isWorking = atom({ plugin: 'companion', key: 'isWorking' } as const, false)
const replyMood = atom({ plugin: 'companion', key: 'replyMood' } as const, null)
const isSleeping = atom({ plugin: 'companion', key: 'isSleeping' } as const, false)
const limits = atom({ plugin: 'companion', key: 'limits' } as const, [] as Limit[])
const look = atom({ plugin: 'companion', key: 'look' } as const, { items: [] })
const sprites = atom({ plugin: 'companion', key: 'sprites' } as const, {} as SpriteSet)
// The default is the project tab: a board shared by every project buries the rows of the one you opened.
const view = atom({ plugin: 'companion', key: 'view' } as const, 'project' as View)

/**
 * The board file can be edited outside the conversation (by the model, by hand), so it is re-read
 * every minute as well as at the end of each turn. The look queue and the sprite file's modification
 * time are checked on the same beat.
 */
const REFRESH_MS = 60_000

/** State one activation keeps between events. It is an argument rather than a variable of `register` because `$` can only be passed to functions declared at the top of this file. */
type Cell = {
  runtime: Promise<Runtime> | undefined
  /** The sprite file's modification time as of the last load, shared by the timer and the Reload button. -2 until the first load. */
  spritesMtime: number
}

/**
 * The runtime (settings plus environment), resolved once per activation: the environment cannot change
 * meanwhile and the pane renders often.
 */
function runtimeOf($: EngineInterface, options: PluginOptions, cell: Cell): Promise<Runtime> {
  // Each `$.env.get` takes a string literal on purpose: the engine reads the names a module uses off its
  // source, and a name passed through a variable makes the module fail to load.
  cell.runtime ??= (async () =>
    buildRuntime(readSettings(options), {
      home: (await $.env.get('HOME')) || undefined,
      claudeConfigDir: await $.env.get('CLAUDE_CONFIG_DIR'),
      lcAll: await $.env.get('LC_ALL'),
      lcMessages: await $.env.get('LC_MESSAGES'),
      lang: await $.env.get('LANG'),
    }))().catch((error: unknown) => {
    // A rejected promise must not stay cached, or every later event would fail the same way for the rest of the session.
    cell.runtime = undefined
    throw error
  })

  return cell.runtime
}

/** Re-reads the board into state. If the read fails the previous value stays (a file caught mid-write must not blank the pane). */
async function refreshBoard($: EngineInterface, rt: Runtime): Promise<void> {
  if (rt.boardFile === undefined) return
  try {
    const parsed: Board = parseBoard(await $.fs.read(rt.boardFile), await $.clock.now())
    await update($, board, () => parsed)
  } catch {
    // Keep showing the previous value. If the file was never readable, the pane says so.
  }
}

/** The result of reading the queue file. */
type QueueRead =
  | { state: 'ok'; queue: LookQueue }
  /** The file exists but is unreadable or not a queue. It must be left untouched. */
  | { state: 'broken' }
  /** There is no place to keep a queue (no config directory). */
  | { state: 'unavailable' }

/** Reads the queue file. A missing file is an empty queue; an existing file that cannot be used is `broken`. */
async function readQueue($: EngineInterface, rt: Runtime): Promise<QueueRead> {
  if (rt.queueFile === undefined) return { state: 'unavailable' }
  try {
    if (!(await $.fs.exists(rt.queueFile))) return { state: 'ok', queue: { items: [] } }
    const queue = parseQueue(await $.fs.read(rt.queueFile))

    return queue === null ? { state: 'broken' } : { state: 'ok', queue }
  } catch {
    return { state: 'broken' }
  }
}

/**
 * Writes a file through a temporary neighbour and `mv`, so a reader (another session) never sees a
 * half-written file. The file API has no rename, hence the `mv` command; where it is unavailable the
 * file is written in place instead, which is what a plain write would have done anyway.
 */
async function writeAtomic($: EngineInterface, path: string, text: string): Promise<void> {
  const temp = `${path}.${Math.random().toString(36).slice(2, 8)}.tmp`
  await $.fs.write(temp, text)
  try {
    const moved = await $.process.run(['mv', '-f', '--', temp, path], { timeoutMs: COMMAND_TIMEOUT_MS })
    if (moved.exitCode === 0) return
  } catch {
    // Fall through to the in-place write.
  }
  await $.fs.write(path, text)
  await $.process.run(['rm', '-f', '--', temp], { timeoutMs: COMMAND_TIMEOUT_MS }).catch(() => undefined)
}

/** What a queue change reports: done, or why nothing was written. */
type QueueChange = 'ok' | 'broken' | 'unavailable'

/**
 * Applies a change to the queue file. It reads the file again just before writing, because another
 * session may have added items since the last read; a broken file is never overwritten.
 *
 * There is no locking: two sessions changing the queue at the same instant can lose one of the updates
 * (read-modify-write). The window is milliseconds and a lost item is only re-listed, so a lock was not worth its failure modes.
 */
async function changeQueue($: EngineInterface, rt: Runtime, change: (queue: LookQueue) => LookQueue): Promise<QueueChange> {
  const current = await readQueue($, rt)
  if (current.state !== 'ok') return current.state
  if (rt.queueFile === undefined) return 'unavailable'
  const next = change(current.queue)
  await writeAtomic($, rt.queueFile, `${JSON.stringify(next, null, 2)}\n`)
  await update($, look, () => next)

  return 'ok'
}

/** Re-reads the queue on the board's interval, to pick up items other sessions added. A broken or unavailable queue shows nothing. */
async function refreshLook($: EngineInterface, rt: Runtime): Promise<void> {
  const current = await readQueue($, rt)
  await update($, look, () => (current.state === 'ok' ? current.queue : { items: [] }))
}

/** Reads the sprite file into state. Missing, unreadable or invalid gives no art. Remembers the file's mtime (-1 when it cannot be stat-ed). */
async function loadSprites($: EngineInterface, rt: Runtime, cell: Cell): Promise<void> {
  let set: SpriteSet = {}
  let mtimeMs = -1
  if (rt.spritesFile !== undefined) {
    try {
      const stat = await $.fs.stat(rt.spritesFile)
      mtimeMs = stat.mtimeMs
      // Size first: reading and decoding an oversized file would stall the pane. Its mtime is still
      // remembered, so the timer does not retry it until the file changes.
      if (stat.size <= MAX_SPRITE_FILE_BYTES) set = parseSprites(await $.fs.read(rt.spritesFile))
    } catch {
      set = {}
    }
  }
  cell.spritesMtime = mtimeMs
  await update($, sprites, () => set)
}

/** Whether the sprite file changed since the last load: a cheap `stat` only, so it can run on the timer. A file that appeared or vanished counts. */
async function hasSpritesChanged($: EngineInterface, rt: Runtime, cell: Cell): Promise<boolean> {
  if (rt.spritesFile === undefined) return false
  try {
    return (await $.fs.stat(rt.spritesFile)).mtimeMs !== cell.spritesMtime
  } catch {
    return cell.spritesMtime !== -1
  }
}

/** Whether a command can be started, judged by `which`. */
async function hasCommand($: EngineInterface, command: string): Promise<boolean> {
  try {
    return (await $.process.run(['which', command], { timeoutMs: COMMAND_TIMEOUT_MS })).exitCode === 0
  } catch {
    return false
  }
}

/**
 * Where a path really leads: its kind and its fully resolved path (every symbolic link followed), or
 * undefined when it does not exist, is a dangling link, or the engine withheld the resolved path.
 * Every decision about a path is made on this resolved path, never on the name that was given: a link
 * called `a.png` can point at a `.command` file.
 */
async function resolvePath($: EngineInterface, path: string): Promise<{ kind: 'file' | 'dir' | 'other'; realPath: string } | undefined> {
  try {
    const stat = await $.fs.stat(path, { resolve: true })

    return stat.realPath === undefined ? undefined : { kind: stat.kind, realPath: stat.realPath }
  } catch {
    return undefined
  }
}

/** Whether `realPath` lies in the session folder (itself resolved, so a linked project folder compares like with like). */
async function isInSessionFolder($: EngineInterface, realPath: string): Promise<boolean> {
  const folder = await resolvePath($, await $.session.cwd())

  return folder !== undefined && folder.kind === 'dir' && isInside(realPath, folder.realPath)
}

/**
 * Judges whether a target may be opened at all, without opening it. A path is resolved with
 * `$.fs.stat` (it must exist; the resolved path's kind and extension decide), a URL is only parsed.
 * Shared by `ask_to_look`, which must decide before it lists anything, and the Open button.
 *
 * `isAutomatic` is true for `ask_to_look`: html, htm and svg then open only inside the session folder.
 * The Open button passes false, because pressing it is the user's own decision.
 *
 * The plan carries the resolved path, not the name given, so the opener gets the file that was judged.
 */
async function decideOpen(
  $: EngineInterface,
  target: string,
  isAutomatic: boolean,
): Promise<{ decision: OpenDecision; isMissing: boolean }> {
  let subject = target
  let kind: 'file' | 'dir' | 'other' = 'file'
  let isActiveAllowed = true
  if (target.startsWith('/')) {
    const real = await resolvePath($, target)
    if (real === undefined) return { decision: { ok: false, reason: 'invalid' }, isMissing: true }
    subject = real.realPath
    kind = real.kind
    // Looked up only for the types it matters for.
    if (isAutomatic && kind === 'file' && ACTIVE_CONTENT_EXTENSIONS.has(extensionOf(subject))) {
      isActiveAllowed = await isInSessionFolder($, subject)
    }
  }
  const uname = await $.process.run(['uname', '-s'], { timeoutMs: COMMAND_TIMEOUT_MS }).then(
    ran => ran.stdout,
    () => '',
  )
  const platform = detectPlatform(await $.env.get('WSL_DISTRO_NAME'), uname)
  // `code` is only looked up when it can matter.
  const hasCode = subject.startsWith('/') && kind === 'file' ? await hasCommand($, 'code') : false

  return { decision: planOpen(platform, subject, hasCode, kind, isActiveAllowed), isMissing: false }
}

/**
 * Runs a plan. On WSL a file path is converted with `wslpath -w` first, because `explorer.exe` does not
 * understand Linux paths. Resolves to undefined when it ran, or to the reason when it did not.
 */
async function runPlan($: EngineInterface, plan: OpenPlan, lang: Lang): Promise<string | undefined> {
  try {
    const [command, argument] = plan.argv
    let where = argument
    if (plan.convertWslPath) {
      const converted = await $.process.run(['wslpath', '-w', argument], { timeoutMs: COMMAND_TIMEOUT_MS })
      where = converted.stdout.trim()
      if (converted.exitCode !== 0 || where === '') {
        return `wslpath failed (exit ${converted.exitCode}): ${converted.stderr.trim() || 'no output'}`
      }
      // Planning already refused commas, but the converted form is what explorer.exe parses.
      if (where.includes(',')) return messages(lang).refusal('comma-on-wsl')
    }
    const ran = await $.process.run([command, where], { timeoutMs: COMMAND_TIMEOUT_MS })

    return !plan.isExitCodeReliable || ran.exitCode === 0 ? undefined : `${command} exited with ${ran.exitCode}: ${ran.stderr.trim()}`
  } catch (error) {
    return error instanceof Error ? error.message : String(error)
  }
}

/** Opens a queue item (the Open button). A refusal or a failure is shown as a toast and the item stays unread. */
async function openItem($: EngineInterface, rt: Runtime, item: LookItem): Promise<void> {
  const m = messages(rt.lang)
  const { decision } = await decideOpen($, item.target, false)
  const failure = decision.ok ? await runPlan($, decision.plan, rt.lang) : m.refusal(decision.reason)
  if (failure !== undefined) {
    $.ui.toast(m.openFailed(failure))
    return
  }
  const openedAt = await $.clock.now()
  await changeQueue($, rt, queue => markOpened(queue, item.id, openedAt))
}

/**
 * The `ask_to_look` tool: lists a deliverable in the pane and opens it right away when the allowlist
 * (open.ts) permits.
 *
 * The tool handler answers without calling `next`, so the engine's permission check never sees the
 * call. That is why the opener is limited to files that are safe to hand to the system and why
 * directories are refused: the model chooses `target`, and a launcher must never run what it names.
 *
 * Order: validate -> add to the queue -> open. A file the allowlist does not cover (and no editor to
 * open it) is still listed so the user can find it, but is not opened, and the result says so.
 */
async function askToLook($: EngineInterface, rt: Runtime, input: { target?: unknown; title?: unknown; note?: unknown }) {
  const m = messages(rt.lang)
  const asked = prepareAsk(input, m)
  if ('deny' in asked) return { deny: asked.deny }

  const { decision, isMissing } = await decideOpen($, asked.target, true)
  if (isMissing) return { deny: m.toolBadTarget(asked.target) }
  if (!decision.ok && decision.reason === 'not-a-file') return { deny: m.toolNotFile(asked.target) }

  const now = await $.clock.now()
  const item: LookItem = {
    id: `${now.toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    title: asked.title,
    // A URL is listed in its normalised form, so the same page in two spellings is one item.
    target: asked.classified.kind === 'url' ? asked.classified.href : asked.target,
    ...(asked.note ? { note: asked.note } : {}),
    addedAt: now,
    cwd: await $.session.cwd(),
  }
  const saved = await changeQueue($, rt, queue => addItem(queue, item))
  if (saved === 'unavailable') return { deny: m.toolNoQueue }
  if (saved === 'broken') return { deny: m.toolQueueBroken(rt.queueFile ?? '') }
  if (!decision.ok) return { result: m.toolAddedNotOpened(asked.title, m.refusal(decision.reason)) }
  const failure = await runPlan($, decision.plan, rt.lang)

  return { result: failure === undefined ? m.toolAdded(asked.title) : m.toolAddedButFailed(asked.title, failure) }
}

/** Gathers the state both the pane and the band show, scoped to the open folder and the selected tab. */
async function readScoped($: EngineInterface, rt: Runtime): Promise<Scoped> {
  return scopeOf(await read($, board), await read($, look), await $.session.cwd(), rt.home, await read($, view))
}

/** Copies an absolute path to the clipboard and reports the result in a toast, so you know it landed before pasting. */
async function copyPath($: EngineInterface, rt: Runtime, path: string, surface: RenderInput<'Pane'>['surface']): Promise<void> {
  const m = messages(rt.lang)
  const copied = await $.ui.copy({ text: path, surface })
  $.ui.toast(copied.isCopied ? m.pathCopied(path) : m.copyFailed(copied.reason))
}

/**
 * The companion mod: keeps the board's in-progress / blocked / review sections and the "please look"
 * queue in a side pane, and shows a one-line band above the prompt with the last turn's duration.
 * This file wires the events and does the file and command work; drawing and the pure rules are in
 * the neighbouring modules.
 */
export const register: Register = (on, options) => {
  // Settings come from the manifest's userConfig and are fixed for this activation (a change reloads the mod).
  const settings = readSettings(options)
  const cell: Cell = { runtime: undefined, spritesMtime: -2 }
  // A reload in the middle of a turn restarts these counts; the band is only a rough guide, so that is accepted.
  let startedAt = 0
  let tools = 0

  on('session.start', async ($, e, next) => {
    const rt = await runtimeOf($, options, cell)
    const m = messages(rt.lang)
    try {
      await $.command.register({ name: 'board', description: m.commandDescription })
      await $.tool.register({
        name: 'ask_to_look',
        description: m.toolDescription,
        inputSchema: {
          type: 'object',
          properties: {
            target: { type: 'string', description: m.toolTargetDescription },
            title: { type: 'string', description: m.toolTitleDescription },
            note: { type: 'string', description: m.toolNoteDescription },
          },
          required: ['target', 'title'],
        },
      })
    } catch (error) {
      // Without the command or the tool the pane and the timer are still worth starting; say what is missing.
      $.ui.toast(m.setupFailed(error instanceof Error ? error.message : String(error)))
    }
    await refreshBoard($, rt)
    await refreshLook($, rt)
    await loadSprites($, rt, cell)
    try {
      // A fresh session has no earlier values, so read the engine's last report (often empty until the first response).
      const { rateLimits } = await $.session.usage()
      await update($, limits, () => rateLimits)
    } catch {
      // Usage is a nicety; the pane and the timer must still start without it.
    }
    $.clock.every(REFRESH_MS, async () => {
      await refreshBoard($, rt)
      await refreshLook($, rt)
      if (await hasSpritesChanged($, rt, cell)) await loadSprites($, rt, cell)
    })
    // A pane opened unasked only docks beside the conversation at 144 columns or more; /board opens it otherwise.
    if (settings.isAutoOpen) {
      void $.ui.open({ id: PANE, title: m.paneTitle })
    }

    return next(e)
  })

  // The command also brings the status line back after Hide: there is no other way to un-hide it.
  on('command.run', { command: 'board' }, async $ => {
    const rt = await runtimeOf($, options, cell)
    await update($, isBandHidden, () => false)
    await refreshBoard($, rt)
    await $.ui.open({ id: PANE, title: messages(rt.lang).paneTitle })

    return { text: messages(rt.lang).commandReply }
  })

  on('prompt.submit', async ($, e, next) => {
    startedAt = await $.clock.now()
    tools = 0
    await update($, isWorking, () => true)
    // Speaking wakes the character. When the sleep command itself was typed, skill.prompt puts it back to sleep right after.
    if (!isSleepCommand(e.text, settings.sleepSkill)) {
      await update($, isSleeping, () => false)
    }

    return next(e)
  })

  // Fires every time a limit window moves by a point; the pane redraws from the state change.
  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) {
      await update($, limits, () => e.rateLimits)
    }

    return next(e)
  })

  // The matcher cannot be configured at runtime, so the skill name is compared inside the handler.
  // Both the typed slash command and the Skill tool expand the skill, so both pass through here.
  on('skill.prompt', async ($, e, next) => {
    if (isSleepSkill(e.skill, settings.sleepSkill)) {
      await update($, isSleeping, () => true)
    }

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    tools += 1

    return next(e)
  })

  on('tool.call', { tool: LOOK_TOOL }, async ($, e) => askToLook($, await runtimeOf($, options, cell), e))

  on('turn.complete', async ($, e, next) => {
    // Sub-agent turns also end here. Clearing "working" for one would switch the mood back in the
    // middle of the parent's turn.
    if (e.agentId !== undefined) {
      return next(e)
    }
    const rt = await runtimeOf($, options, cell)
    // After a reload in mid-turn startedAt is 0, and "now minus 0" would be decades; keep the previous record instead.
    if (startedAt !== 0) {
      const seconds = Math.round(((await $.clock.now()) - startedAt) / 1000)
      await update($, last, () => ({ seconds, tools }))
    }
    await update($, isWorking, () => false)
    // The mood comes from the reply's wording, not the turn time (time clashed with the content).
    const rows = await $.session.messages()
    const lastReply = [...rows].reverse().find(row => row.role === 'assistant' && row.text.trim())
    await update($, replyMood, () => (lastReply ? moodFromReply(lastReply.text) : null))
    // The board is often edited during a turn, so re-read it at the end.
    await refreshBoard($, rt)

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const rt = await runtimeOf($, options, cell)
    const kit = $.ui.resolve(e)
    const now = await $.clock.now()
    const offset = rt.utcOffset ?? utcOffsetMinutes(now)
    const mood = moodOf(await read($, isWorking), await read($, last), now, await read($, replyMood), await read($, isSleeping), offset)
    const cwd = await $.session.cwd()

    return paneView({
      kit,
      raster: e.surface === 'terminal' ? $.ui.resolve(e).Raster : undefined,
      m: messages(rt.lang),
      width: e.props.bodyColumns,
      bodyRows: e.props.scroll.bodyRows,
      sprite: (await read($, sprites))[mood],
      cwd,
      home: rt.home,
      boardFile: rt.boardFile,
      shown: await readScoped($, rt),
      usage: usageRows(await read($, limits), now, messages(rt.lang), offset),
      offset,
      actions: {
        selectTab: tab => update($, view, () => tab),
        copyCwd: surface => copyPath($, rt, cwd, surface),
        // Reload re-reads everything the pane shows from files: the board, the queue and the art.
        reload: async () => {
          await refreshBoard($, rt)
          await refreshLook($, rt)
          await loadSprites($, rt, cell)
        },
        open: item => openItem($, rt, item),
        done: id => changeQueue($, rt, queue => removeItem(queue, id)),
      },
    })
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isBandHidden))) {
      return next(e)
    }
    const rt = await runtimeOf($, options, cell)
    const now = await $.clock.now()

    return bandView({
      kit: $.ui.resolve(e),
      m: messages(rt.lang),
      name: rt.name,
      isWorking: e.props.isWorking,
      turn: await read($, last),
      now,
      offset: rt.utcOffset ?? utcOffsetMinutes(now),
      // The band counts the same scope as the pane, so switching tabs changes its numbers.
      board: (await readScoped($, rt)).board,
      openPane: () => $.ui.open({ id: PANE, title: messages(rt.lang).paneTitle }),
      hide: () => update($, isBandHidden, () => true),
    })
  })
}

