import type { Messages } from './i18n'
import { MAX_NOTE, MAX_TITLE, cleanLine, isPlainTarget } from './look'
import { classifyTarget, type TargetKind } from './open'

/** The `ask_to_look` input after cleaning, or the text to refuse it with. */
export type AskInput = { deny: string } | { title: string; note: string; target: string; classified: Extract<TargetKind, { kind: 'url' | 'path' }> }

/**
 * Cleans and checks what the model passed to `ask_to_look`, before anything touches the machine.
 * The values are typed as strings but the model controls them, so each is checked at runtime. Title and
 * note are cleaned (control characters become spaces, lengths are capped). The target is never
 * rewritten, because a rewritten path names a different file: one with control characters, newlines or
 * more than 2000 characters is refused, and so is one that is neither an absolute path nor a
 * well-formed http(s) URL.
 */
export function prepareAsk(input: { target?: unknown; title?: unknown; note?: unknown }, m: Messages): AskInput {
  const title = cleanLine(input.title, MAX_TITLE)
  if (!title) return { deny: m.toolEmptyTitle }
  const target = input.target
  if (typeof target !== 'string' || target === '') return { deny: m.toolBadTarget(m.toolEmptyReceived) }
  if (!isPlainTarget(target)) return { deny: m.toolTargetNotPlain }
  const classified = classifyTarget(target)
  if (classified.kind === 'invalid' || classified.kind === 'invalid-url') return { deny: m.toolBadTarget(target) }

  return { title, note: cleanLine(input.note, MAX_NOTE), target, classified }
}

files.hooks/band.tsx:
import type { RenderElement } from 'claude-code'

import type { Board, Turn } from '../types'
import type { Messages } from './i18n'
import type { Kit } from './view-types'
import { ACCENT } from './constants'
import { hourOf } from './time'

/** A turn longer than this gets a remark in the band. Two minutes is about when waiting starts to be felt. */
const LONG_TURN_SECONDS = 120

/** Picks the greeting from the local hour. */
function greeting(now: number, m: Messages, utcOffset: number): string {
  const hour = hourOf(now, utcOffset)
  if (hour >= 5 && hour < 11) return m.greetingMorning
  if (hour >= 11 && hour < 17) return m.greetingDay
  if (hour >= 17 && hour < 24) return m.greetingEvening

  return m.greetingNight
}

/** Band text. Priority: working, the previous turn, then a greeting. */
export function bandLine(isWorking: boolean, turn: Turn | null, now: number, m: Messages, utcOffset = 0): string {
  if (isWorking) {
    return m.bandWorking
  }
  if (turn === null) {
    return greeting(now, m, utcOffset)
  }

  return m.bandFinished(m.duration(turn.seconds), turn.tools, turn.seconds > LONG_TURN_SECONDS)
}

/** Everything the band draws, gathered by register.tsx. */
export type BandInput = {
  kit: Kit
  m: Messages
  name: string
  isWorking: boolean
  turn: Turn | null
  now: number
  /** Offset from UTC in minutes. */
  offset: number
  /** The board as scoped like the pane, for the counts. */
  board: Board | null
  openPane: () => unknown
  hide: () => unknown
}

/** Draws the one-line band above the prompt: name, the status text, the counts, and the Board and Hide buttons. */
export function bandView(p: BandInput): RenderElement {
  const { Box, Button, Text } = p.kit
  const { m, board } = p

  return (
    <Box>
      <Text color={ACCENT}>◦ {p.name} </Text>
      <Text dimColor wrap="truncate-end">
        {bandLine(p.isWorking, p.turn, p.now, m, p.offset)}
        {board !== null && m.bandCounts(board.inProgress.length, board.review.length)}
      </Text>
      <Button key="board" label={m.bandBoardButton} onPress={p.openPane} />
      <Text> </Text>
      <Button key="hide" label={m.bandHideButton} onPress={p.hide} />
    </Box>
  )
}

