import { isInside } from './paths'
import type { Board, BoardItem } from '../types'

/**
 * Board file format (Markdown):
 *
 * ```markdown
 * ## Backlog
 * - [ ] [web][docs] **Write the onboarding guide** — notes after the dash are ignored
 * ## In Progress
 * - [ ] [api] **Rate limiter**
 * ## Blocked
 * ## Review
 * ## Done
 * - [x] ...  (ignored)
 *
 * ## Folders
 * | Tags | Folder |
 * |---|---|
 * | `[web]` `[docs]` | `~/projects/site` |
 * | `[api]` | `~/projects/api` |
 * ```
 *
 * Section headings are English (`Backlog`, `In Progress`, `Blocked`, `Review`) or Japanese
 * (`着手前`, `進行中`, `保留`, `レビュー待ち`). Only unchecked `- [ ]` entries are read; any other
 * section (such as Done) is ignored. The folder table is headed `## Folders` or `## フォルダ`.
 */

/** Section heading to board field. */
const SECTIONS: Record<string, 'backlog' | 'inProgress' | 'blocked' | 'review'> = {
  Backlog: 'backlog',
  'In Progress': 'inProgress',
  Blocked: 'blocked',
  Review: 'review',
  着手前: 'backlog',
  進行中: 'inProgress',
  保留: 'blocked',
  レビュー待ち: 'review',
}

/** Headings of the folder table. Its rows are read until the next `## ` heading. */
const FOLDER_HEADINGS = ['## Folders', '## フォルダ']

/**
 * Extracts the unfinished entries of Backlog / In Progress / Blocked / Review from the board text.
 *
 * Keeping the description would not fit on one pane line, so only the tags and the bold title are kept.
 * Entries in the older format without bold use the leading text after the tags instead.
 */
export function parseBoard(text: string, loadedAt: number): Board {
  const board: Board = { backlog: [], inProgress: [], blocked: [], review: [], folders: parseTagFolders(text), loadedAt }
  let section: (typeof SECTIONS)[string] | null = null

  for (const line of text.split('\n')) {
    const heading = /^## (.+?)\s*$/.exec(line)
    if (heading) {
      section = SECTIONS[heading[1] ?? ''] ?? null
      continue
    }
    if (section === null || !line.startsWith('- [ ] ')) {
      continue
    }
    board[section].push(parseItem(line.slice('- [ ] '.length)))
  }

  return board
}

function parseItem(body: string): BoardItem {
  const tags: string[] = []
  let rest = body
  // Tags may be written `[a][b]` or `[a] [b]`; the pattern eats the whitespace before each.
  let tag = /^\s*\[([^\]]+)\]/.exec(rest)
  while (tag) {
    tags.push(tag[1] ?? '')
    rest = rest.slice(tag[0].length)
    tag = /^\s*\[([^\]]+)\]/.exec(rest)
  }

  rest = rest.trim()
  // Bold is the title only at the start of the line. In the older format a bold span mid-sentence
  // describes status ("M1-M4 done"), not the title.
  const bold = /^\*\*(.+?)\*\*/.exec(rest)
  // Title fallback (no bold at the start): the text after the tags, up to the first " — ", "（", "、" or "。",
  // with `**` removed, cut to 40 characters (roughly one pane line).
  const title = bold?.[1] ?? rest.split(/ — |（|、|。/)[0]?.replaceAll('**', '').slice(0, 40) ?? ''

  return { tags, title }
}

/**
 * Reads the folder-to-tags mapping from the `## Folders` table.
 *
 * Every `[tag]` in the first column is a tag; every backticked path in the second column is a folder
 * (taken by the backticks rather than a separator because folder names may contain spaces). `~` stays
 * unexpanded and is resolved against HOME when matching. Rows without a folder are skipped.
 */
export function parseTagFolders(text: string): Array<{ folder: string; tags: string[] }> {
  const lines = text.split('\n')
  const start = lines.findIndex(line => FOLDER_HEADINGS.includes(line.trim()))
  if (start < 0) {
    return []
  }
  const pairs: Array<{ folder: string; tags: string[] }> = []
  for (const line of lines.slice(start + 1)) {
    if (line.startsWith('## ')) {
      break
    }
    const cells = line.split('|').map(cell => cell.trim())
    // The leading and trailing | leave empty cells, so a two-column table has 4 cells.
    if (!line.startsWith('|') || cells.length < 4) {
      continue
    }
    const tags = [...(cells[1] ?? '').matchAll(/\[([^\]]+)\]/g)].map(m => m[1] ?? '')
    for (const m of (cells[2] ?? '').matchAll(/`([^`]+)`/g)) {
      // A trailing slash would make a prefix test look for `//`, so the folder never matched. A cell
      // that is only slashes is the root and stays `/` (stripping it would leave an empty folder).
      const raw = m[1] ?? ''
      const trimmed = raw.replace(/\/+$/, '')
      pairs.push({ folder: trimmed === '' && raw.startsWith('/') ? '/' : trimmed, tags })
    }
  }

  return pairs
}

/** Replaces a leading `~` with HOME. A path without `~`, or an unknown HOME, is returned as is. */
export function expandHome(path: string, home: string | undefined): string {
  return home && (path === '~' || path.startsWith('~/')) ? `${home}${path.slice(1)}` : path
}

/**
 * Collects the tags that apply to the open folder: a row matches when the folder is the row's folder
 * or lies below it, so opening a subfolder of a project still picks up the project's tags.
 */
export function tagsForFolder(folders: Board['folders'], cwd: string, home: string | undefined): Set<string> {
  const tags = new Set<string>()
  for (const { folder, tags: rowTags } of folders) {
    const path = expandHome(folder, home)
    if (isInside(cwd, path)) {
      for (const tag of rowTags) tags.add(tag)
    }
  }

  return tags
}

/** Keeps only the entries carrying at least one of the given tags. */
export function filterBoard(board: Board, tags: Set<string>): Board {
  const keep = (items: BoardItem[]) => items.filter(item => item.tags.some(tag => tags.has(tag)))

  return {
    ...board,
    backlog: keep(board.backlog),
    inProgress: keep(board.inProgress),
    blocked: keep(board.blocked),
    review: keep(board.review),
  }
}

