import type { LookItem, LookQueue } from '../types'
import { isInside } from './paths'

/**
 * Queue size limit. Past it the oldest entries drop off, so forgetting to press Done never lets the
 * list grow. 15 fits in the pane without pushing the board out (30 filled the whole pane).
 */
export const MAX_ITEMS = 15

/** Longest accepted values of the `ask_to_look` fields. A model could otherwise fill the pane (or the file) with one call. */
export const MAX_TITLE = 120
export const MAX_NOTE = 300
export const MAX_TARGET = 2000
/** Longest accepted item id (ours are about 16 characters). */
const MAX_ID = 64

// The classes are written as escapes on purpose: stripping control characters is the point.
const CONTROLS = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]/
/**
 * Bidirectional controls (embeddings, overrides, isolates, directional marks including the Arabic
 * letter mark) and invisible characters (zero-width space, joiners, word joiner, BOM). They can reorder
 * or hide characters, so a title or target could read as something other than what is stored.
 */
const BIDI = /[\u202a-\u202e\u2066-\u2069\u200e\u200f\u061c\u200b-\u200d\u2060\ufeff]/

/**
 * Makes text safe for one line of the pane: control characters (newlines, tabs, escape sequences)
 * become spaces, bidirectional controls are removed, runs of spaces collapse, and the result is
 * trimmed and cut to `max` characters.
 */
export function cleanLine(value: unknown, max: number): string {
  if (typeof value !== 'string') return ''

  return value
    .replace(new RegExp(BIDI.source, 'g'), '')
    .replace(new RegExp(`${CONTROLS.source}+`, 'g'), ' ')
    .replace(/ {2,}/g, ' ')
    .trim()
    .slice(0, max)
}

/**
 * Whether a `target` can be taken as it is: a string of at most `MAX_TARGET` characters with no control
 * or bidirectional characters. A target is never rewritten (a rewritten path names a different file),
 * so one that fails this is refused (`ask_to_look`) or dropped (the queue file).
 */
export function isPlainTarget(value: unknown): value is string {
  return typeof value === 'string' && value.length <= MAX_TARGET && !CONTROLS.test(value) && !BIDI.test(value)
}

/**
 * Keeps the entries that have the three required strings and rebuilds each from known fields only,
 * with the same cleaning and caps `ask_to_look` applies (the file can be edited by hand or by another
 * tool). An entry whose id or title is empty after cleaning, or whose target is not plain, is dropped.
 */
function validItem(value: unknown): LookItem | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const raw: Record<string, unknown> = { ...value }
  const id = cleanLine(raw['id'], MAX_ID)
  const title = cleanLine(raw['title'], MAX_TITLE)
  const target = raw['target']
  if (id === '' || title === '' || !isPlainTarget(target)) return undefined
  const note = cleanLine(raw['note'], MAX_NOTE)
  const cwd = cleanLine(raw['cwd'], MAX_TARGET)

  return {
    id,
    title,
    target,
    ...(note ? { note } : {}),
    addedAt: typeof raw['addedAt'] === 'number' && Number.isFinite(raw['addedAt']) ? raw['addedAt'] : 0,
    ...(typeof raw['openedAt'] === 'number' && Number.isFinite(raw['openedAt']) ? { openedAt: raw['openedAt'] } : {}),
    ...(cwd ? { cwd } : {}),
  }
}

/**
 * Reads the queue JSON. Items without a usable `id`, `title` and `target` are dropped (the pane
 * would fail to draw them), and the rest are rebuilt from the known fields.
 *
 * Returns null when a non-empty text cannot be read as a queue at all (broken JSON, or no `items`
 * array). The caller must then leave the file alone instead of writing an empty queue over what may be
 * a half-written or hand-edited file. A blank text is an empty queue.
 */
export function parseQueue(text: string): LookQueue | null {
  if (text.trim() === '') return { items: [] }
  try {
    const data: unknown = JSON.parse(text)
    const items = typeof data === 'object' && data !== null && 'items' in data ? data.items : undefined
    if (!Array.isArray(items)) return null
    // Trim on read too, in case the limit was lowered or the file edited by hand; the file itself
    // shrinks at the next write.
    return { items: items.flatMap(one => validItem(one) ?? []).slice(0, MAX_ITEMS) }
  } catch {
    return null
  }
}

/**
 * Adds one item. If the same target is already listed, it moves to the top with the new title and
 * becomes unread again (the usual case is fixing a deliverable and showing it again, so no duplicates).
 */
export function addItem(queue: LookQueue, item: LookItem): LookQueue {
  const rest = queue.items.filter(one => one.target !== item.target)

  return { items: [item, ...rest].slice(0, MAX_ITEMS) }
}

/** Removes an item (the Done button). */
export function removeItem(queue: LookQueue, id: string): LookQueue {
  return { items: queue.items.filter(one => one.id !== id) }
}

/** Records when Open was pressed; the pane dims opened items. */
export function markOpened(queue: LookQueue, id: string, at: number): LookQueue {
  return { items: queue.items.map(one => (one.id === id ? { ...one, openedAt: at } : one)) }
}

/**
 * Narrows the queue to the open folder's items. An item matches when its folder equals the open one
 * or either lies below the other (an item added at a project root stays visible from a subfolder
 * session). Items without a recorded folder never match.
 */
export function itemsForFolder(queue: LookQueue, cwd: string): LookItem[] {
  return queue.items.filter(
    one =>
      one.cwd !== undefined &&
      (isInside(one.cwd, cwd) || isInside(cwd, one.cwd)),
  )
}

