import type { Mood, ReplyMood, Turn } from '../types'
import { hourOf } from './time'

/**
 * Every mood the pane can show, as a runtime list. The sprite generator reads this list, so it is the
 * single source of the names; the `Mood` type is declared in types/index.d.ts (that file may not import)
 * and the check below makes the compiler fail when the two disagree in either direction.
 */
export const MOODS = ['idle', 'think', 'smile', 'worry', 'wave', 'sleep'] as const satisfies readonly Mood[]

type Assert<T extends true> = T
/** Fails to compile when a `Mood` is missing from `MOODS`. */
export type MoodsAreComplete = Assert<Mood extends (typeof MOODS)[number] ? true : false>

export type { Mood, ReplyMood }

// Both languages are always matched, whatever the UI language is: replies are often written in a
// language other than the UI's.
const WORRY = new RegExp(
  [
    'ごめん|すまない|失敗|できなかった|できてなかった|うまくいかなかった|うまくいってない|間違え|間違って|消えてた|壊れ|ずれてた|残念|足りなかった|見落とし',
    "\\b(sorry|apologi[sz]e|failed|failure|mistake|my bad|i broke|broke|broken|couldn't|could not|unfortunately|missed|overlooked)\\b",
  ].join('|'),
  'gi',
)
const SMILE = new RegExp(
  [
    'できた|できたよ|よかった|通った|完成|完璧|そろった|うまくいった|直した|直ったよ|反映した|成功|ばっちり|ありがとう',
    '\\b(done|fixed|passed|passing|works|working now|great|thanks|thank you|success(ful)?|completed?|all green|perfect)\\b',
  ].join('|'),
  'gi',
)
const ASK = new RegExp(
  [
    '[？?]\\s*$|どうする|決めて|どれにする|選んで|教えて|確認させて|いい[？?]|どうかな',
    '\\b(which (one|option|do|would|should)|should i|let me know|would you like|do you want|any preference)\\b',
  ].join('|'),
  'i',
)

/** The last this-many characters count double: a reply's conclusion usually comes last. */
const TAIL = 300

/**
 * Chooses a mood from the wording of a reply.
 *
 * It used to follow the turn duration, which clashed with the content (a smile on an apology).
 * Wording is not always right either, since this is only keyword matching. If scenes turn up that it
 * misses, the next step is to let a small model classify the reply.
 *
 * - A closing paragraph that asks something gives `think` (the decision is handed back to the user).
 * - Otherwise apology and success words are counted, the tail counting double, and the larger wins.
 *   A tie goes to `worry`: a report that apologises and fixes should read as the apology.
 * - No keyword at all gives `idle`.
 */
export function moodFromReply(text: string): ReplyMood {
  const body = text.trim()
  if (!body) return 'idle'
  const lastParagraph = body.split(/\n\s*\n/).filter(p => p.trim()).at(-1) ?? body
  if (ASK.test(lastParagraph.trim())) return 'think'

  const tail = body.slice(-TAIL)
  const count = (re: RegExp, s: string) => (s.match(re) ?? []).length
  const worry = count(WORRY, body) + count(WORRY, tail)
  const smile = count(SMILE, body) + count(SMILE, tail)
  if (worry === 0 && smile === 0) return 'idle'

  return worry >= smile ? 'worry' : 'smile'
}

/**
 * The pane's mood. Sleeping wins, then working (think); after a turn the mood from the reply's
 * wording (moodFromReply). With no reply yet it follows the time of day: wave in the morning
 * (05:00 up to 11:00), idle otherwise.
 */
export function moodOf(
  working: boolean,
  turn: Turn | null,
  now: number,
  reply: ReplyMood | null = null,
  sleeping = false,
  utcOffset = 0,
): Mood {
  // The sleep routine also runs as a turn, but the sleeping face should win over the thinking face.
  if (sleeping) return 'sleep'
  if (working) return 'think'
  if (reply !== null) return reply
  if (turn !== null) return 'idle'
  const hour = hourOf(now, utcOffset)

  return hour >= 5 && hour < 11 ? 'wave' : 'idle'
}

files.hooks/open.ts:
/** Where the mod runs, which decides the opener command. */
export type Platform = 'wsl' | 'macos' | 'linux'

/**
 * Picks the platform. WSL is told apart by its distro variable because `uname` reports plain Linux
 * there; otherwise `uname -s` output decides (`Darwin` is macOS, anything else is treated as Linux).
 */
export function detectPlatform(wslDistro: string | undefined, uname: string): Platform {
  if (wslDistro) return 'wsl'

  return uname.trim() === 'Darwin' ? 'macos' : 'linux'
}

/**
 * Things to look at, opened in the system's default app: web pages, images and PDF. Nothing else is
 * ever handed to the system opener, because it would launch executables, scripts, shortcuts and
 * application bundles (`.exe`, `.bat`, `.lnk`, `.command`, `.desktop`, `.app`) just as readily.
 */
export const SYSTEM_VIEW_EXTENSIONS: ReadonlySet<string> = new Set(['html', 'htm', 'png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'pdf'])

/**
 * Plain-text documents. They are safe for the system opener too (and open there when the code editor
 * is missing), but the code editor is preferred because a reader of Markdown or JSON usually wants text.
 */
export const SYSTEM_TEXT_EXTENSIONS: ReadonlySet<string> = new Set(['md', 'markdown', 'txt', 'csv', 'json'])

/**
 * Types that run script when a browser opens them (`.html` and `.svg` can carry JavaScript). Of the
 * system-opened types these are the only active ones; `ask_to_look` opens them automatically only
 * inside the session folder.
 */
export const ACTIVE_CONTENT_EXTENSIONS: ReadonlySet<string> = new Set(['html', 'htm', 'svg'])

/** The lower-case extension of a path's last component, without the dot; empty when it has none. */
export function extensionOf(path: string): string {
  const name = path.slice(path.lastIndexOf('/') + 1)
  const dot = name.lastIndexOf('.')

  return dot <= 0 ? '' : name.slice(dot + 1).toLowerCase()
}

/**
 * Normalises an http(s) URL. Returns its `href` (spaces, quotes and other unsafe characters are
 * percent-encoded by the parser) or undefined for anything that does not parse or uses another scheme.
 * The caller must pass the returned href on, never the original text.
 */
export function parseHttpUrl(target: string): string | undefined {
  try {
    const url = new URL(target)

    return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : undefined
  } catch {
    return undefined
  }
}

/** Whether the target is a URL the mod accepts. Only http(s) is, so the tool is not a way to launch arbitrary schemes. */
export function isUrl(target: string): boolean {
  return parseHttpUrl(target) !== undefined
}

/** What kind of thing the target names, judged from its text alone (no file system access). */
export type TargetKind =
  | { kind: 'url'; href: string }
  | { kind: 'path'; path: string }
  /** Has a scheme but is not a well-formed http(s) URL (`file:`, `javascript:`, a URL with a space in the host, ...). */
  | { kind: 'invalid-url' }
  /** Neither an absolute path nor a URL. */
  | { kind: 'invalid' }

/**
 * Classifies a target. An absolute path starts with `/`; anything starting with a scheme is parsed as
 * a URL and must be http(s). A Windows drive path (`C:\x`) looks like a scheme and is rejected as a URL,
 * which is right: the mod passes Linux paths only.
 */
export function classifyTarget(target: string): TargetKind {
  if (target.startsWith('/')) return { kind: 'path', path: target }
  if (/^[a-z][a-z0-9+.-]*:/i.test(target)) {
    const href = parseHttpUrl(target)

    return href === undefined ? { kind: 'invalid-url' } : { kind: 'url', href }
  }

  return { kind: 'invalid' }
}

/** Why a target was not opened. The target may still be listed (`needs-editor`). */
export type OpenRefusal =
  | 'invalid'
  | 'invalid-url'
  /** A directory or something else that is not a regular file (a macOS `.app` bundle is a directory). */
  | 'not-a-file'
  /** The extension is not on the system-opener allowlist and the `code` editor is not installed. */
  | 'needs-editor'
  /** On WSL: `explorer.exe` splits its command line on commas, so a target containing one could become two arguments. */
  | 'comma-on-wsl'
  /** An html/htm/svg file outside the session folder, which `ask_to_look` lists but does not open by itself. */
  | 'outside-session'

/** The command to run to open a target, decided without touching the machine. */
export type OpenPlan = {
  /** Executable followed by its single argument. For a WSL file the argument is still a Linux path. */
  argv: [string, string]
  /** Convert the path with `wslpath -w` before running (WSL system opener on a file). */
  convertWslPath: boolean
  /** Whether the exit code means anything. `explorer.exe` returns 1 even when it opened the target. */
  isExitCodeReliable: boolean
}

/** The outcome of `planOpen`: a command, or the reason there is none. */
export type OpenDecision = { ok: true; plan: OpenPlan } | { ok: false; reason: OpenRefusal }

/**
 * Chooses how to open a target, or refuses.
 * - A well-formed http(s) URL goes to the system opener (`explorer.exe` on WSL, `open` on macOS,
 *   `xdg-open` on Linux) as the parsed `href`.
 * - A regular file with a web/image/PDF extension goes to the system opener.
 * - A regular file with a plain-text extension goes to `code` when it is installed, otherwise the system opener.
 * - Any other regular file goes to `code` when it is installed, otherwise it is refused.
 * - Directories and other non-files are refused whatever their name.
 * - On WSL a target containing a comma is refused, because `explorer.exe` splits its command line there.
 * - An html/htm/svg file is refused (`outside-session`) when `isActiveAllowed` is false: the caller
 *   passes false for automatic opening outside the session folder, true for the user's own Open press.
 *
 * `fileKind` is what `$.fs.stat` said about a path, and a path target must be the *resolved* path
 * (symlinks followed), so the extension and the kind describe the same file; both are ignored for URLs.
 */
export function planOpen(
  platform: Platform,
  target: string,
  hasCode: boolean,
  fileKind: 'file' | 'dir' | 'other' = 'file',
  isActiveAllowed = true,
): OpenDecision {
  const classified = classifyTarget(target)
  if (classified.kind === 'invalid-url') return { ok: false, reason: 'invalid-url' }
  if (classified.kind === 'invalid') return { ok: false, reason: 'invalid' }
  if (classified.kind === 'url') {
    return platform === 'wsl' && classified.href.includes(',')
      ? { ok: false, reason: 'comma-on-wsl' }
      : { ok: true, plan: systemPlan(platform, classified.href, false) }
  }
  if (fileKind !== 'file') return { ok: false, reason: 'not-a-file' }
  if (platform === 'wsl' && classified.path.includes(',')) return { ok: false, reason: 'comma-on-wsl' }

  const ext = extensionOf(classified.path)
  if (ACTIVE_CONTENT_EXTENSIONS.has(ext) && !isActiveAllowed) return { ok: false, reason: 'outside-session' }
  if (SYSTEM_VIEW_EXTENSIONS.has(ext)) return { ok: true, plan: systemPlan(platform, classified.path, true) }
  if (hasCode) return { ok: true, plan: { argv: ['code', classified.path], convertWslPath: false, isExitCodeReliable: true } }
  if (SYSTEM_TEXT_EXTENSIONS.has(ext)) return { ok: true, plan: systemPlan(platform, classified.path, true) }

  return { ok: false, reason: 'needs-editor' }
}

function systemPlan(platform: Platform, argument: string, isFile: boolean): OpenPlan {
  if (platform === 'wsl') {
    return { argv: ['explorer.exe', argument], convertWslPath: isFile, isExitCodeReliable: false }
  }

  return { argv: [platform === 'macos' ? 'open' : 'xdg-open', argument], convertWslPath: false, isExitCodeReliable: true }
}

/** How long an opener or a helper command may run before it is killed. Openers return as soon as they hand the target to the desktop; `xdg-open` with no handler can hang for the default 30 seconds. */
export const COMMAND_TIMEOUT_MS = 5000

