/**
 * Whether `path` is `dir` itself or lies below it. The boundary is a path separator, so `/a/bc` is not
 * inside `/a/b`, and a root `dir` of `/` contains every absolute path (the naive `${dir}/` prefix would
 * look for `//`). Both arguments must already be normalised absolute paths; this does not touch the disk.
 */
export function isInside(path: string, dir: string): boolean {
  if (path === dir) return true

  return path.startsWith(dir.endsWith('/') ? dir : `${dir}/`)
}

