import type { Elements, RenderElement, RenderSurface } from 'claude-code'

import type { BoardItem, LookItem, Sprite, View } from '../types'
import type { Messages } from './i18n'
import { isUrl } from './open'
import { shortenHome, type Scoped } from './scope'
import { ACCENT } from './constants'
import { formatClock } from './time'
import type { Kit } from './view-types'
import { USAGE_TRACK, usageBar, usageColor, type UsageRow } from './usage'

/**
 * Estimate of how many lines the pane content (without the art) takes, used to decide whether the art
 * can be pinned to the bottom. Every pane text is truncated to one line, so wrapping is not counted.
 * The blank line after each section (marginBottom) is counted.
 */
export function paneRows(p: {
  tabs: boolean
  /** Number of usage windows (heading + one line each + margin; an empty state takes one line). Omit for no usage section. */
  usage?: number
  folder: boolean
  look: number
  sections: BoardItem[][] | null
}): number {
  let rows = (p.tabs ? 2 : 0) + (p.usage === undefined ? 0 : 2 + Math.max(p.usage, 1)) + (p.folder ? 2 : 0) + (p.look > 0 ? p.look * 2 + 2 : 0)
  if (p.sections === null) {
    return rows + 2
  }
  for (const items of p.sections) {
    const body = items.reduce((sum, item) => sum + (item.tags.length > 0 ? 2 : 1), 0)
    rows += 1 + Math.max(body, 1) + 1
  }

  return rows + 1
}

/** What the pane does when a button is pressed; wired to the engine by register.tsx. */
export type PaneActions = {
  selectTab: (tab: View) => unknown
  /** Copies the open folder's path; `surface` is where the press happened. */
  copyCwd: (surface: RenderSurface) => unknown
  /** Re-reads the board, the queue and the sprite file. */
  reload: () => unknown
  open: (item: LookItem) => unknown
  done: (id: string) => unknown
}

/** Everything the pane draws, gathered by register.tsx. */
export type PaneInput = {
  kit: Kit
  /** Only the terminal surface has Raster; undefined elsewhere. */
  raster: Elements['terminal']['Raster'] | undefined
  m: Messages
  actions: PaneActions
  /** Pane width and visible height in cells. */
  width: number
  bodyRows: number
  sprite: Sprite | undefined
  cwd: string
  home: string | undefined
  /** The board file; undefined when none could be located (the pane then says so). */
  boardFile: string | undefined
  shown: Scoped
  usage: UsageRow[]
  /** Offset from UTC in minutes, for the "read at" clock. */
  offset: number
}

/** Draws the side pane: tabs, usage bars, the open folder, the "please look" list, the board sections and the art. */
export function paneView(p: PaneInput): RenderElement {
  const { Box, Button, Text } = p.kit
  const { m, home, width, actions, shown, usage, sprite, cwd } = p
  let art = null
  // Raster only exists in the terminal for now. In a pane narrower than the art, omit it rather than show it cut off.
  if (sprite !== undefined && p.raster !== undefined && width >= sprite.columns) {
    const Raster = p.raster
    art = (
      <Box marginTop={1} flexShrink={0}>
        <Raster key="sprite" columns={sprite.columns} rows={sprite.rows} cells={sprite.cells} />
      </Box>
    )
  }

  const current = shown.board
  // The open folder (moved here from the band, which is one line wide). Pressing it copies the absolute path.
  const hasFolder = !shown.hasProject || shown.view === 'project'
  const folderRow = hasFolder && (
    <Box marginBottom={1}>
      <Text dimColor>{m.folderLabel}</Text>
      <Button key="copy-cwd" label={shortenHome(cwd, home)} onPress={press => actions.copyCwd(press.surface)} />
    </Box>
  )
  // Usage is stacked vertically, one window per row, each with a bar. The bar length is what is left
  // of the pane width after the label, the percentage and the reset time. Shown on every tab.
  const barCells = Math.min(Math.max(width - 30, 6), 30)
  const usageRow = (
    <Box flexDirection="column" marginBottom={1}>
      <Text bold color={ACCENT}>
        {m.usageHeading}
      </Text>
      {usage.length === 0 && <Text dimColor>{m.usageEmpty}</Text>}
      {usage.map(row => {
        const [filled, part, rest] = usageBar(row.percent, barCells)
        const fill = usageColor(row.percent, ACCENT)

        return (
          <Text wrap="truncate-end">
            {row.label}{' '}
            <Text color={fill}>{filled}</Text>
            {/* The partial block leaves its right side transparent, so its background is the track colour to fill the gap */}
            <Text color={fill} backgroundColor={USAGE_TRACK}>
              {part}
            </Text>
            <Text color={USAGE_TRACK}>{'█'.repeat(rest)}</Text> {`${row.percent}%`.padStart(4)}
            <Text dimColor>{row.until ? `  ${m.usageUntil(row.until)}` : ''}</Text>
          </Text>
        )
      })}
    </Box>
  )
  // Tabs are always shown. A folder missing from the table has an empty project tab, so it gets Board and Backlog only.
  const tabList: Array<[View, string]> = shown.hasProject
    ? [['project', m.tabProject], ['all', m.tabAll], ['backlog', m.tabBacklog]]
    : [['all', m.tabBoard], ['backlog', m.tabBacklog]]
  const tabs = (
    <Box marginBottom={1}>
      {tabList.map(([key, label]) => (
        <Box marginRight={1}>
          {shown.view === key ? (
            <Text bold color={ACCENT}>
              [{label}]
            </Text>
          ) : (
            <Button key={`tab-${key}`} label={label} onPress={() => actions.selectTab(key)} />
          )}
        </Box>
      ))}
    </Box>
  )
  // With no items the section is left out, so the usual pane looks like the board alone.
  const lookSection = shown.items.length > 0 && (
    <Box flexDirection="column" marginBottom={1}>
      <Text bold color={ACCENT}>
        {m.lookHeading(shown.items.length)}
      </Text>
      {shown.items.map(item => (
        <Box flexDirection="column">
          <Box>
            <Text wrap="truncate-end" bold={item.openedAt === undefined} dimColor={item.openedAt !== undefined}>
              {'・'}
              {item.title}{' '}
            </Text>
            <Button key={`open-${item.id}`} label={m.open} onPress={() => actions.open(item)} />
            <Text> </Text>
            <Button key={`done-${item.id}`} label={m.done} onPress={() => actions.done(item.id)} />
          </Box>
          <Text dimColor wrap="truncate-start">
            {'  '}
            {item.note ? `${item.note} · ` : ''}
            {isUrl(item.target) ? item.target : shortenHome(item.target, home)}
          </Text>
        </Box>
      ))}
    </Box>
  )

  const rows = paneRows({
    tabs: true,
    usage: usage.length,
    folder: hasFolder,
    look: shown.items.length,
    sections:
      current === null ? null : shown.view === 'backlog' ? [current.backlog] : [current.inProgress, current.blocked, current.review],
  })
  // The art sits at the bottom of the pane. When the content fits the window, a spacer pins it to the
  // bottom; when it overflows, the art follows the content (the pane scrolls the whole tree as one,
  // so there is no way to keep only the art fixed).
  const layout = (content: RenderElement) =>
    art !== null && sprite !== undefined && rows + sprite.rows + 1 <= p.bodyRows ? (
      <Box flexDirection="column" width={width} height={p.bodyRows}>
        <Box flexDirection="column" flexGrow={1}>
          {content}
        </Box>
        {art}
      </Box>
    ) : (
      <Box flexDirection="column" width={width}>
        {content}
        {art}
      </Box>
    )

  if (current === null) {
    return layout(
      <Box flexDirection="column">
        {tabs}
        {usageRow}
        {folderRow}
        {lookSection}
        <Text dimColor>{p.boardFile === undefined ? m.boardNoPath : m.boardUnreadable(p.boardFile)}</Text>
        <Button key="reload" label={m.reload} onPress={actions.reload} />
      </Box>,
    )
  }

  const section = (label: string, items: BoardItem[]) => (
    <Box flexDirection="column" marginBottom={1}>
      <Text bold color={ACCENT}>
        {label} {items.length}
      </Text>
      {items.length === 0 && <Text dimColor>{m.sectionEmpty}</Text>}
      {items.map(item => (
        <Box flexDirection="column">
          <Text wrap="truncate-end">
            {'・'}
            {item.title}
          </Text>
          {item.tags.length > 0 && (
            <Text dimColor wrap="truncate-end">
              {'  '}
              {item.tags.join(' ')}
            </Text>
          )}
        </Box>
      ))}
    </Box>
  )

  const footer = (
    <Box>
      <Text dimColor>{m.readAt(formatClock(current.loadedAt, p.offset))}</Text>
      <Button key="reload" label={m.reload} onPress={actions.reload} />
    </Box>
  )

  return layout(
    <Box flexDirection="column">
      {tabs}
      {usageRow}
      {folderRow}
      {lookSection}
      {shown.view === 'backlog' ? (
        section(m.sectionBacklog, current.backlog)
      ) : (
        <>
          {section(m.sectionInProgress, current.inProgress)}
          {section(m.sectionBlocked, current.blocked)}
          {section(m.sectionReview, current.review)}
        </>
      )}
      {footer}
    </Box>,
  )
}

