import type { Board, LookItem, LookQueue, View } from '../types'
import { filterBoard, tagsForFolder } from './board'
import { itemsForFolder } from './look'

/** Abbreviates a path under HOME with `~`. Display only, never used to resolve a path. */
export function shortenHome(path: string, home: string | undefined): string {
  if (home && (path === home || path.startsWith(`${home}/`))) {
    return `~${path.slice(home.length)}`
  }

  return path
}

/**
 * The "please look" items shown on a tab. They appear on the leftmost tab only: the other tabs are for
 * surveying the board, and the list would crowd it out. A folder missing from the folder table has
 * Board as its leftmost tab (whose content is everything), so it lists all items. In a project, only
 * the items added from that folder are listed.
 */
export function lookItemsFor(tab: View, hasProject: boolean, queue: LookQueue, cwd: string): LookItem[] {
  if (tab === 'backlog' || (hasProject && tab === 'all')) return []
  if (!hasProject) return queue.items

  return itemsForFolder(queue, cwd)
}

/** What the pane and the band show after the folder and the selected tab are applied. */
export type Scoped = { board: Board | null; items: LookItem[]; hasProject: boolean; view: View }

/**
 * Decides what the pane and the band show. When the open folder is in the folder table, the selected
 * tab applies. Otherwise the project tab would be empty, so the whole board is shown whatever was selected.
 */
export function scopeOf(current: Board | null, queue: LookQueue, cwd: string, home: string | undefined, picked: View): Scoped {
  const tags = current === null ? new Set<string>() : tagsForFolder(current.folders, cwd, home)
  const hasProject = tags.size > 0
  // A folder outside the table has no project tab, so a stored "project" choice reads as "all".
  const chosen: View = picked === 'project' && !hasProject ? 'all' : picked
  const items = lookItemsFor(chosen, hasProject, queue, cwd)
  // The Backlog tab shows the whole Backlog even inside a project (unstarted work is meant to be surveyed across projects).
  if (chosen !== 'project' || current === null) {
    return { board: current, items, hasProject, view: chosen }
  }

  return { board: filterBoard(current, tags), items, hasProject, view: chosen }
}

