import type { PluginOptions } from 'claude-code'

import { expandHome } from './board'
import { resolveLang, type Lang } from './i18n'
import { parseUtcOffset } from './time'

/** Defaults of the settings, mirrored in the manifest's `userConfig`. */
export const DEFAULT_NAME = 'Companion'
export const DEFAULT_SLEEP_SKILL = 'sleep'

/** The plugin's own folder under the Claude config directory: the queue file and the sprite file live here. */
const DATA_DIR = 'companion'

/**
 * The user's settings, from the manifest's `userConfig` (see .claude-plugin/plugin.json). The engine
 * hands them to `register(on, options)` once per activation; changing one reloads the mod, so nothing
 * here is re-read later.
 */
export type Settings = {
  /** `auto` follows the system locale. */
  language: 'auto' | Lang
  name: string
  /** Empty means the default, `<config dir>/board.md`. */
  boardPath: string
  sleepSkill: string
  /** Minutes from UTC for displayed times; undefined uses the host's offset. */
  utcOffset: number | undefined
  /** Whether the pane opens by itself at session start. */
  isAutoOpen: boolean
}

function text(options: PluginOptions, key: string): string {
  const value = options[key]

  return typeof value === 'string' ? value.trim() : ''
}

/**
 * Reads the settings out of the options. A missing or wrongly typed value falls back to the default
 * instead of failing, since the pane should still open with a half-filled configuration.
 */
export function readSettings(options: PluginOptions): Settings {
  const language = text(options, 'language').toLowerCase()
  const autoOpen = options['auto_open_pane']

  return {
    language: language === 'en' || language === 'ja' ? language : 'auto',
    name: text(options, 'character_name') || DEFAULT_NAME,
    boardPath: text(options, 'board_path'),
    sleepSkill: text(options, 'sleep_skill') || DEFAULT_SLEEP_SKILL,
    utcOffset: parseUtcOffset(text(options, 'utc_offset')),
    isAutoOpen: typeof autoOpen === 'boolean' ? autoOpen : true,
  }
}

/** The settings plus what the environment decides: language, home and the files the mod reads and writes. */
export type Runtime = Settings & {
  lang: Lang
  home: string | undefined
  /** Where the mod keeps its files and where the default board lives. Undefined when neither CLAUDE_CONFIG_DIR nor HOME is set. */
  configDir: string | undefined
  /** The board file to read. Undefined when it cannot be located (no HOME for the default or a `~` path). */
  boardFile: string | undefined
  /** The look-queue file. Undefined without a config dir: the queue is then neither read nor written. */
  queueFile: string | undefined
  /** The runtime sprite file (written by tools/build_sprites.py). */
  spritesFile: string | undefined
}

/**
 * Works out the config directory: `CLAUDE_CONFIG_DIR` when set, else `~/.claude`. Pure so the
 * branches can be tested; an empty value counts as unset.
 */
export function configDirOf(claudeConfigDir: string | undefined, home: string | undefined): string | undefined {
  const configured = claudeConfigDir?.trim()
  if (configured) {
    const expanded = expandHome(configured, home)
    // A `~` that could not be expanded would be a relative path named "~", so treat it as unusable.
    if (!expanded.startsWith('~')) return expanded.length > 1 ? expanded.replace(/\/+$/, '') : expanded
  }

  return home ? `${home}/.claude` : undefined
}

/** Combines the settings with the environment into the paths and language the mod works with. */
export function buildRuntime(
  settings: Settings,
  env: { home?: string; claudeConfigDir?: string; lcAll?: string; lcMessages?: string; lang?: string },
): Runtime {
  const configDir = configDirOf(env.claudeConfigDir, env.home)
  const custom = settings.boardPath ? expandHome(settings.boardPath, env.home) : undefined
  const boardFile = custom !== undefined ? (custom.startsWith('~') ? undefined : custom) : configDir !== undefined ? `${configDir}/board.md` : undefined
  const data = configDir === undefined ? undefined : `${configDir}/${DATA_DIR}`

  return {
    ...settings,
    lang: resolveLang(settings.language === 'auto' ? undefined : settings.language, env.lcAll, env.lcMessages, env.lang),
    home: env.home,
    configDir,
    boardFile,
    queueFile: data === undefined ? undefined : `${data}/look-queue.json`,
    spritesFile: data === undefined ? undefined : `${data}/sprites.json`,
  }
}

