/**
 * Whether the typed text starts the sleep skill. A slash command can arrive already expanded, so both
 * the typed form and the expanded form are checked.
 */
export function isSleepCommand(text: string, skill: string): boolean {
  const escaped = skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

  return new RegExp(`^\\s*/${escaped}(?![\\w-])`).test(text) || text.includes(`<command-name>/${skill}</command-name>`)
}

/**
 * Whether a `skill.prompt` event is the sleep skill. A plugin skill arrives namespaced
 * (`plugin:skill`), so the suffix after a colon counts too.
 */
export function isSleepSkill(skill: string, sleepSkill: string): boolean {
  return skill === sleepSkill || skill.endsWith(`:${sleepSkill}`)
}

