import type { Sprite, SpriteSet } from '../types'
import { MOODS } from './mood'

/**
 * The sprite file, written by `tools/build_sprites.py` and read here at runtime (no art ships with the
 * mod, and nothing is generated into the source). Default location: `<config dir>/companion/sprites.json`.
 *
 * ```json
 * {
 *   "version": 1,
 *   "sprites": {
 *     "idle":  { "columns": 24, "rows": 12, "cells": "<base64>" },
 *     "think": { "columns": 24, "rows": 12, "cells": "<base64>" }
 *   }
 * }
 * ```
 *
 * - Moods are those of `MOODS` in mood.ts (idle, think, smile, worry, wave, sleep). A mood that is
 *   absent shows no art. Unknown moods are ignored.
 * - `columns` x `rows` is the size in terminal cells; one cell is two vertically stacked dots (half block).
 * - `cells` is the base64 of `columns * rows` little-endian triples of uint32: the character code
 *   (0x2580 upper half, 0x2584 lower half, 0x20 blank), the foreground and the background. A colour is
 *   `0xRRGGBB`, or `0x01000000` for the terminal's default. This is the `cells` shape `Raster` takes.
 */
export const SPRITE_FILE_VERSION = 1

/** Sprite files larger than this are not read. Real ones are tens of kilobytes; this stops a wrong or hostile file from stalling the pane. */
export const MAX_SPRITE_FILE_BYTES = 4 * 1024 * 1024

/** A sprite larger than this in either direction is not drawn: the pane is never that wide. */
const MAX_SIDE = 200

/** Bytes per cell in `cells`: three little-endian uint32. */
const BYTES_PER_CELL = 12

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** The terminal's default colour in a cell. */
const DEFAULT_COLOUR = 0x01000000

/** Decodes standard base64 (already checked to be unpadded multiples of four characters) into bytes. */
function decodeBase64(text: string): number[] {
  const bytes: number[] = []
  for (let i = 0; i < text.length; i += 4) {
    const n = [0, 1, 2, 3].reduce((acc, k) => acc * 64 + BASE64.indexOf(text.charAt(i + k)), 0)
    bytes.push((n >> 16) & 255, (n >> 8) & 255, n & 255)
  }

  return bytes
}

/**
 * Whether every cell is something the pane can draw. The engine refuses a whole drawing when one cell
 * holds a code point that is not a printable width-1 character, which would blank the pane, so a bad
 * file is rejected here instead. Allowed: the blank (0x20) and the block elements (0x2580-0x259F, which
 * the generator uses), with colours as 0xRRGGBB or the terminal default.
 */
function hasDrawableCells(cells: string): boolean {
  const bytes = decodeBase64(cells)
  const word = (at: number) => ((bytes[at] ?? 0) | ((bytes[at + 1] ?? 0) << 8) | ((bytes[at + 2] ?? 0) << 16)) + (bytes[at + 3] ?? 0) * 2 ** 24
  for (let at = 0; at < bytes.length; at += BYTES_PER_CELL) {
    const char = word(at)
    if (char !== 0x20 && (char < 0x2580 || char > 0x259f)) return false
    if ([word(at + 4), word(at + 8)].some(colour => colour !== DEFAULT_COLOUR && colour > 0xffffff)) return false
  }

  return true
}

function validSprite(value: unknown): Sprite | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const { columns, rows, cells } = { ...value } as Record<string, unknown>
  if (typeof columns !== 'number' || typeof rows !== 'number' || typeof cells !== 'string') return undefined
  if (!Number.isInteger(columns) || !Number.isInteger(rows) || columns < 1 || rows < 1 || columns > MAX_SIDE || rows > MAX_SIDE) return undefined
  // base64 of n bytes is 4*ceil(n/3) characters; n is a multiple of 12, so there is no padding and the
  // length is exact. Length and alphabet are checked first so the decoder below only sees well-formed input.
  if (cells.length !== ((columns * rows * BYTES_PER_CELL) / 3) * 4 || !/^[A-Za-z0-9+/]+$/.test(cells)) return undefined
  if (!hasDrawableCells(cells)) return undefined

  return { columns, rows, cells }
}

/**
 * Reads the sprite file's text. A file that does not parse, has another version, or has no `sprites`
 * object gives no art at all; a single bad mood entry is skipped and the others are kept.
 */
export function parseSprites(text: string): SpriteSet {
  try {
    const data: unknown = JSON.parse(text)
    if (typeof data !== 'object' || data === null) return {}
    const root = { ...data } as Record<string, unknown>
    const table = root['sprites']
    if (root['version'] !== SPRITE_FILE_VERSION || typeof table !== 'object' || table === null) return {}
    const entries = table as Record<string, unknown>
    const set: SpriteSet = {}
    for (const mood of MOODS) {
      const sprite = validSprite(entries[mood])
      if (sprite !== undefined) set[mood] = sprite
    }

    return set
  } catch {
    return {}
  }
}

