files.hooks/time.ts:
/**
 * Parses the UTC-offset setting: `+09:00`, `-05:30`, `+9` or `9`. Returns undefined when unset or malformed,
 * so the host's offset is used. The override exists because the zone the mod runtime reports is not guaranteed
 * to be the user's (a UTC container, a remote host); times in the pane would then be hours off.
 * Hours go up to 14 (the largest real offset) and minutes must be 0 to 59.
 */
export function parseUtcOffset(text: string | undefined): number | undefined {
  const match = /^([+-])?(\d{1,2})(?::?(\d{2}))?$/.exec(text?.trim() ?? '')
  if (!match) return undefined
  const extra = Number(match[3] ?? 0)
  if (extra > 59) return undefined
  const minutes = Number(match[2]) * 60 + extra
  if (minutes > 14 * 60) return undefined

  return match[1] === '-' ? -minutes : minutes
}

/**
 * The host's offset from UTC at that moment, in minutes. Read here and passed down, so the functions
 * that format times stay pure and testable.
 */
export function utcOffsetMinutes(now: number): number {
  return -new Date(now).getTimezoneOffset()
}

/** The hour of day (0-23) at an offset from UTC. */
export function hourOf(now: number, utcOffset: number): number {
  return new Date(now + utcOffset * 60_000).getUTCHours()
}

/** `HH:MM` at an offset from UTC. */
export function formatClock(ms: number, utcOffset: number): string {
  const d = new Date(ms + utcOffset * 60_000)

  return `${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}`
}

