import type { Limit } from '../types'
import type { Messages } from './i18n'

/** One row of the usage display. `until` is the reset time (HH:MM today, otherwise MM/DD HH:MM), empty when unknown. */
export type UsageRow = { label: string; percent: number; until: string }

/** Above this percentage the bar turns to the warning colour, so a nearly used window stands out. */
export const USAGE_WARN = 80

/** Colour of a bar: the warning colour past `USAGE_WARN` (80% itself is still normal), otherwise the accent. */
export function usageColor(percent: number, accent: string): string {
  return percent > USAGE_WARN ? 'red' : accent
}

/** Colour of the empty part of a bar: a muted warm grey that does not stand out on a dark background. */
export const USAGE_TRACK = '#4A4440'

/** Width in terminal columns. Full-width characters take two (needed to align labels like "5時間"). */
function displayWidth(text: string): number {
  return [...text].reduce((sum, ch) => sum + (/[ -~]/.test(ch) ? 1 : 2), 0)
}

/**
 * Turns the limit windows into rows. Labels are padded to equal width so the bars start in one column
 * (CJK labels count double). Times are in the machine's local zone, passed as an offset because
 * the pure functions here must not depend on the host's timezone.
 *
 * A percentage that is not a finite number (the engine reported nothing usable) counts as 0, so the
 * bar and the figure stay drawable.
 */
export function usageRows(windows: Limit[], now: number, m: Messages, utcOffset = 0): UsageRow[] {
  const shift = utcOffset * 60_000
  const day = (ms: number) => new Date(ms + shift).toISOString().slice(0, 10)
  const labels: Record<string, string> = { five_hour: m.limitFiveHour, seven_day: m.limitSevenDay }
  const rows = windows.map(w => {
    const at = w.resetsAt === undefined ? NaN : Date.parse(w.resetsAt)
    const local = Number.isNaN(at) ? '' : new Date(at + shift).toISOString()
    const until = local === '' ? '' : day(at) === day(now) ? local.slice(11, 16) : `${local.slice(5, 7)}/${local.slice(8, 10)} ${local.slice(11, 16)}`

    return { label: labels[w.kind] ?? w.kind, percent: Number.isFinite(w.percentUsed) ? w.percentUsed : 0, until }
  })
  const width = Math.max(0, ...rows.map(row => displayWidth(row.label)))

  return rows.map(row => ({ ...row, label: row.label + ' '.repeat(width - displayWidth(row.label)) }))
}

/**
 * A horizontal bar. Each cell has 8 levels so the end is drawn to a fraction. Returns
 * [filled cells, one partial character, remaining cell count]; the caller paints them in separate colours.
 * The remainder is not drawn with the shade character: its mesh fades unevenly from row to row and
 * made the bar look broken. A non-finite percentage draws an empty bar.
 */
export function usageBar(percent: number, cells: number): [string, string, number] {
  const safe = Number.isFinite(percent) ? percent : 0
  const eighths = Math.round((Math.min(Math.max(safe, 0), 100) / 100) * cells * 8)
  const full = Math.floor(eighths / 8)
  const part = eighths % 8 === 0 ? '' : (' ▏▎▍▌▋▊▉'[eighths % 8] ?? '')

  return ['█'.repeat(full), part, cells - full - (part ? 1 : 0)]
}

