files.types/index.d.ts:
/** One board entry, taken from a line like `- [ ] [tag][tag] **Title** — notes`. */
export type BoardItem = { tags: string[]; title: string }

/** What the pane and the band read from the board file: only the sections they display. */
export type Board = {
  inProgress: BoardItem[]
  blocked: BoardItem[]
  review: BoardItem[]
  /** Unfinished Backlog entries, shown on the Backlog tab. */
  backlog: BoardItem[]
  /** Folder-to-tags rows of the `## Folders` table, used to scope the project tab. `~` is left unexpanded. */
  folders: Array<{ folder: string; tags: string[] }>
  /** When the file was last read successfully (milliseconds). */
  loadedAt: number
}

/** Every mood the pane can show. The contract file must be self-contained (no imports), so the list lives here; hooks/mood.ts checks `MOODS` against it at compile time. */
export type Mood = 'idle' | 'think' | 'smile' | 'worry' | 'wave' | 'sleep'

/** The moods a reply's wording can select; the rest of `Mood` come from state. */
export type ReplyMood = 'smile' | 'worry' | 'think' | 'idle'

/** One character image in the shape `Raster` takes directly (generated by tools/build_sprites.py). */
export type Sprite = { columns: number; rows: number; cells: string }

/** The sprites loaded from `<config dir>/companion/sprites.json`, by mood. A mood without an entry shows no art. */
export type SpriteSet = Partial<Record<Mood, Sprite>>

/** One entry of the "please look" queue. The model adds it with `ask_to_look`; the user removes it with Done. */
export type LookItem = {
  id: string
  title: string
  /** An absolute path or an http(s) URL. */
  target: string
  note?: string
  addedAt: number
  /** When Open was last pressed. Absent while unread. */
  openedAt?: number
  /** The session folder that added the item. Scopes the leftmost tab; items without it never match a folder. */
  cwd?: string
}

/** Pane tabs. `project` and `all` are scopes of the in-progress sections; `backlog` lists unstarted work. */
export type View = 'project' | 'all' | 'backlog'

/** Contents of the look-queue file. Newest first. */
export type LookQueue = { items: LookItem[] }

/** Record of the previous turn, shown in the band. */
export type Turn = { seconds: number; tools: number }

/** One rate-limit window (same shape as the engine's SessionRateLimit). `kind` is e.g. five_hour or seven_day. */
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

declare module 'claude-code' {
  /** Arguments of the `ask_to_look` tool, declared here so the tool name type-checks without a connected server. */
  interface McpToolInputs {
    mcp__companion__ask_to_look: { target: string; title: string; note?: string }
  }

  interface PluginState {
    companion: {
      board: Board | null
      last: Turn | null
      isBandHidden: boolean
      /** Whether a turn is running. Unlike the band, the pane does not receive isWorking in its props. */
      isWorking: boolean
      look: LookQueue
      /** Mood chosen from the last reply's text (hooks/mood.ts). Null until a reply exists. */
      replyMood: ReplyMood | null
      /** True from the start of the sleep skill until the user next speaks. The pane shows the sleeping sprite. */
      isSleeping: boolean
      /** Rate-limit windows from the last response. Empty until the first report. */
      limits: Limit[]
      view: View
      /** Character art read at runtime from the sprite file. Empty when the file is missing or invalid. */
      sprites: SpriteSet
    }
  }
}
